public class Main {
    public static void main(String[] args) {
        int statusCode = 404;
        String statusMeaning;

        switch (statusCode) {
            case 200:
                statusMeaning = "OK - Request Succeeded";
                break;
            case 301:
                statusMeaning = "Moved Permanently";
                break;
            case 400:
                statusMeaning = "Bad Request - Invalid Payload";
                break;
            case 401:
            case 403:
                statusMeaning = "Authentication or Permission Denied";
                break;
            case 404:
                statusMeaning = "Resource Not Found";
                break;
            case 500:
                statusMeaning = "Internal Server Error";
                break;
            default:
                statusMeaning = "Unknown HTTP Status Code";
                break;
        }

        System.out.println("HTTP " + statusCode + ": " + statusMeaning);
    }
}

